"  // Find messenger tabs
  const tabs = await chrome.tabs.query({ url: ["*://*.messenger.com/*", "*://*.facebook.com/*"] });

  // Try to find the active tab first, otherwise use the first one
  let targetTab = tabs.find(t => t.active) || tabs[0];

  if (!targetTab) {
    setMsgStatus('لم يتم العثور على صفحة ماسنجر أو فيسبوك! افتح المحادثة أولاً.', 'error');
    return;
  }
  const msgTabId = targetTab.id;

  isMsgRunning = true;
  msgStopRequested = false;
  btnMsgStart.disabled = true;
  btnMsgStop.disabled = false;
  msgProgressW.style.display = 'block';
  msgLogList.innerHTML = '';
  setMsgStatus('بدأ الإرسال...', 'info');

  const total = msgLines.length;
  let sentCount = 0;

  for (let i = 0; i < total; i++) {
    if (msgStopRequested) break;

    const text = msgLines[i];
    msgCounter.textContent = `${i + 1} / ${total}`;
    msgProgressB.style.width = `${((i + 1) / total) * 100}%`;
    setMsgStatus(`جاري إرسال الرسالة ${i + 1}...`, 'info');

    try {
      // First try to inject the script dynamically in case it wasn't loaded (e.g., after extension update)
      try {
        await chrome.scripting.executeScript({
          target: { tabId: msgTabId },
          files: ['messenger-script.js']
        });
      } catch (injectErr) {
        // Ignore injection errors (it might already be injected or we don't have permission)
      }

      const res = await chrome.tabs.sendMessage(msgTabId, { type: 'SEND_MESSENGER_ROW', text });
      if (res && res.success) {
        addMsgLog(text, true);
        sentCount++;
      } else {
        addMsgLog(`${text} - ${(res&&res.error)||'غير معروف'}`, false);
      }
    } catch (e) {
      addMsgLog(`${text} - خطأ في الاتصال بالصفحة: ${e.message}`, false);
    }"

