"msgCsvInput.addEventListener('change', e => {
  const file = e.target.files[0];
  if (!file) return;
  const reader = new FileReader();
  reader.onload = ev => {
    const text = ev.target.result;

    // Parse CSV lines respecting double quotes
    let lines = [];
    let currentLine = '';
    let inQuotes = false;
    for (let i = 0; i < text.length; i++) {
        let c = text[i];
        if (c === '"') inQuotes = !inQuotes;
        if ((c === '\n' || c === '\r') && !inQuotes) {
            if (c === '\r' && text[i+1] === '\n') i++; // skip \n of \r\n
            if (currentLine.trim()) lines.push(currentLine);
            currentLine = '';
        } else {
            currentLine += c;
        }
    }
    if (currentLine.trim()) lines.push(currentLine);

    // Auto-detect and skip the header row (if it contains 'رقم الطلب' or 'اسم العميل')
    if (lines.length > 0 && (lines[0].includes('رقم الطلب') || lines[0].includes('اسم العميل'))) {
        lines.shift(); // Remove the header row
    }

    // Clean up: replace internal newlines, commas, tabs, semicolons with spaces, and remove quotes
