"// Remove existing listener if any
if (window.portalAutoFillerListener) {
  try {
    chrome.runtime.onMessage.removeListener(window.portalAutoFillerListener);
  } catch(e) {}
}

// Define the new listener
window.portalAutoFillerListener = (msg, _sender, sendResponse) => {
  if (!msg?.action) return;
  (async () => {
    try {
      if (msg.action === 'RUN_SINGLE') sendResponse(await runSingleLineWithRouter(msg));
      else if (msg.action === 'START_QUEUE') {
        const tasks = msg.tasks || [];
        await chrome.storage.local.set({ 
            taskQueue: tasks.slice(1), 
            taskResults: [],
            processingTabId: msg.tabId 
        });
        await chrome.storage.local.remove(['taskRetryFlag']);
        await clearCurrentTask();
        await startNextTask(tasks);
        sendResponse({ ok: true });
      }
      else if (msg.action === 'STOP_QUEUE') {
        // Stop ALL — clear queue and current task
        await chrome.storage.local.set({ taskQueue: [] });
        await chrome.storage.local.remove(['taskRetryFlag']);
        await clearCurrentTask();
        notifyStatus('batch', 'stopped', 'تم إيقاف الكل');
        sendResponse({ ok: true });
      }
      else if (msg.action === 'SKIP_TASK') {
        // Skip only current task — continue with queue
        const { taskQueue } = await chrome.storage.local.get({ taskQueue: [] });
        await chrome.storage.local.remove(['taskRetryFlag']);
        const skippedId = msg.taskId;
        notifyStatus(skippedId, 'stopped', '⏭ تم التخطي');
        await clearCurrentTask();
        if (taskQueue.length > 0) { await sleep(500); await startNextTask(taskQueue); }
        else { notifyStatus('batch', 'batch-done', 'اكتمل Batch'); chrome.runtime.sendMessage({ type: 'BATCH_DONE_STORAGE' }).catch(()=>{}); }
        sendResponse({ ok: true });
      }
      else sendResponse({ ok: true });
    } catch { sendResponse({ ok: false }); }
  })(); return true;
};

