"async function sendToTab(tabId, message, timeout = 8000) {
  return new Promise(async resolve => {
    const timer = setTimeout(() => resolve({ error: 'response-timeout' }), timeout);

    const send = () => {
      chrome.tabs.sendMessage(tabId, message, resp => {
        if (chrome.runtime.lastError) {
          const err = chrome.runtime.lastError.message;
          if (err.includes('Could not establish connection') || err.includes('Receiving end does not exist')) {
            console.warn('[AutoFiller] Portal content script not responding. Re-injecting...');
            chrome.scripting.executeScript({
              target: { tabId: tabId },
              files: ['polyfill.js', 'content-script.js']
            }, () => {
              setTimeout(() => {
                chrome.tabs.sendMessage(tabId, message, retryResp => {
                  clearTimeout(timer);
                  if (chrome.runtime.lastError) resolve({ error: chrome.runtime.lastError.message });
                  else resolve(retryResp || { error: 'no-response' });
                });
              }, 1000);
            });
          } else {
            clearTimeout(timer);
            resolve({ error: err });
          }
        } else {
          clearTimeout(timer);
          resolve(resp || { error: 'no-response' });
        }
      });
    };

    send();
  });
}"

