"// messenger-script.js

// Wait to ensure we only run on Messenger/Facebook Messages pages
if (window.location.hostname.includes('messenger.com') || window.location.pathname.includes('/messages/')) {

    // Remove existing listener if any to prevent duplicate or dead listeners
    if (window.messengerAutomatorListener) {
        try {
            chrome.runtime.onMessage.removeListener(window.messengerAutomatorListener);
        } catch (e) {
            console.log('[Messenger Automator] Could not remove old listener:', e);
        }
    }

    // Define the new listener
    window.messengerAutomatorListener = (message, sender, sendResponse) => {
        if (message.type === 'SEND_MESSENGER_ROW') {
            sendMessengerMessage(message.text)
                .then(success => sendResponse({ success }))
                .catch(err => {
                    console.error('[Messenger Automator] Error:', err);
                    sendResponse({ success: false, error: err.message });
                });
            return true; // Keep message channel open for async response
        }
    };

    // Register the new listener
    chrome.runtime.onMessage.addListener(window.messengerAutomatorListener);
    console.log('[Messenger Automator] Initialized/Updated listener and waiting for commands.');
}"

