    if (lexical) return lexical;

    // 3. Walk ALL elements — check contentEditable JS property (catches plaintext-only too)
    const all = document.querySelectorAll('*');
    for (const el of all) {
      const ce = el.contentEditable;           // JS property, not attribute
      if (ce === 'true' || ce === 'plaintext-only') return el;
    }

    // 4. Shadow DOM traversal (last resort)
    function walkShadow(root) {
      for (const el of root.querySelectorAll('*')) {
