"async function closeTelemetryOrder(status = 'success', completionPct = null) {
  try {
    const { activeSession } = await chrome.storage.local.get('activeSession');
    if (!activeSession?.currentOrder) return;
    const order = activeSession.currentOrder;
    order.finalizedAt = new Date().toISOString();
    order.durationMs = Date.now() - new Date(order.startedAt).getTime();
    order.status = status;
    if (completionPct !== null) order.completionPct = completionPct;

    // Infer completion from page context if not given
    if (completionPct === null) {
      const feat = await getActivePageFeature().catch(() => 'PAGE_1');
      order.completionPct = feat === 'PAGE_3' ? 100 : feat === 'PAGE_2' ? 66 : 33;
    }

    activeSession.orders.push(order);
    activeSession.currentOrder = null;
    await chrome.storage.local.set({ activeSession });
    log('✅ Order closed:', order.orderId, `(${order.completionPct}%)`);
    chrome.runtime.sendMessage({ type: 'SESSION_ORDER_DONE', orderId: order.orderId }).catch(() => {});
  } catch(e) { warn('closeTelemetryOrder failed', e); }
