"async function executePage3_Resolution(data, cfg) {
  const FR = {};
  log('【 PAGE 3 】 Preparing Resolution/Fault Codes...');
  try {
    const { currentTask } = await chrome.storage.local.get({ currentTask: null });
    if (currentTask) notifyStatus(currentTask.taskId, 'filling', 'جاري تعبئة الصفحة الثالثة (الأعطال)...');
  } catch(e){}
  await sleep(1000);

  const isInstall = /تركيب/.test(data.reportType) || isInstallationReport();

  // Determine the fault code(s) to use
  if (data.forceDrainCleaning) {
    // ── Drain Cleaning Flow: Add BOTH drain + periodic maintenance codes ──
    log('🚿 Force Drain Cleaning: adding drain code (AC004) + periodic maintenance code...');

    // Pass both primary and sub fault codes to be entered in the same modal
    FR.faultDrain = await addFaultCodePage3('AC004', '*صيانة');
    log(FR.faultDrain?.ok ? '✅ Drain + Maintenance code added' : '⚠️ Drain + Maintenance code failed');

  } else if (isInstall) {
    // Installation: search 'تركيب' and pick the one with 'تركيب وتشغيل'
    FR.fault = await addFaultCodePage3('*تركيب');
  } else if (/تنظيف|صرف/.test(data.reportType) || /تنظيف|صرف/.test(data.notes || '')) {
    FR.fault = await addFaultCodePage3('AC004');
  } else if (data.faultCode) {
    FR.fault = await addFaultCodePage3(data.faultCode);
  }

  log('━━━ PAGE 3 DONE ━━━', FR);
  return { report: { fieldResults: FR } };
}"

